sp_ListarUsuario	ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION	CREATE DEFINER=`root`@`%` PROCEDURE `sp_ListarUsuario`(\n\n    IN p_idEmpresa INT\n\n)\nBEGIN\n\n    SELECT\n\n        u.idUsuario,\n\n        u.Nome,\n\n        u.Login,\n\n        u.CPF,\n\n        u.Email,\n\n        u.Telefone,\n\n        u.cargo_id,\n\n        c.Nome AS NomeCargo,\n\n        u.dthCriacao,\n\n        u.fAtivo\n\n    FROM Usuario u\n\n    INNER JOIN Cargo c ON c.idCargo = u.cargo_id\n\n    WHERE u.idEmpresa = p_idEmpresa\n\n    ORDER BY u.Nome;\n\nEND	utf8mb4	utf8mb4_0900_ai_ci	utf8mb4_0900_ai_ci
